input.dsl:
workspace "Bank Portal" "C4 model of the online banking platform" {

    !identifiers hierarchical

    model {

        customer = person "Bank Customer" "A customer of the bank who manages their accounts, moves money, and tracks their activity"

        bankPortal = softwareSystem "Bank Portal" "The online banking platform, owned and operated by our company" {

            webPortal = container "Web Portal" "Where customers log in and manage their accounts" "Web application" "Web"
            mobileAppBackend = container "Mobile App Backend" "Serves the bank's mobile app" "REST API"
            accountService = container "Account Service" "Holds the customer account records" "Microservice"
            transactionService = container "Transaction Service" "Processes deposits, withdrawals, and transfers" "Microservice"
            paymentService = container "Payment Service" "Executes card payments and bank transfers" "Microservice"
            cardService = container "Card Service" "Manages debit and credit cards" "Microservice"
            fraudDetectionService = container "Fraud Detection Service" "Scores transactions for fraud" "Microservice"
            notificationService = container "Notification Service" "Sends email and SMS alerts" "Microservice"
            onboardingService = container "Onboarding Service" "Verifies new customers" "Microservice"
            statementsService = container "Statements Service" "Generates monthly statements" "Microservice"
            directDebitService = container "Direct Debit Service" "Processes standing orders and direct debits" "Microservice"
            exchangeRatesService = container "Exchange Rates Service" "Provides currency conversion rates" "Microservice"
            batchScheduler = container "Batch Scheduler" "Runs the nightly interest calculation and reconciliation" "Batch job"
            eventQueue = container "Event Queue" "Carries internal events between the application parts" "Message queue" "Queue"
            ledgerDb = container "Ledger Database" "Stores every account movement" "Database" "Database"
            customerDb = container "Customer Database" "Stores account and profile records" "Database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail" "Database" "Database"
            cache = container "Cache" "Stores sessions and frequently read account data" "In-memory cache" "Cache"
            documentStore = container "Document Store" "Holds the generated statement PDFs" "Document store" "DocumentStore"
        }

        cardPaymentNetwork = softwareSystem "Card Payment Network" "Routes card authorisations; operated by a different organization" "External"
        creditReferenceAgency = softwareSystem "Credit Reference Agency" "Performs credit checks; operated by a different organization" "External"

        customer -> bankPortal.webPortal "logs in and manages accounts, moves money, and tracks activity" "HTTPS"
        customer -> bankPortal.mobileAppBackend "uses the bank's mobile app to manage accounts, move money, and track activity" "HTTPS"

        bankPortal.webPortal -> bankPortal.accountService "manages accounts via" "HTTPS"
        bankPortal.webPortal -> bankPortal.transactionService "submits deposits, withdrawals, and transfers via" "HTTPS"
        bankPortal.webPortal -> bankPortal.paymentService "initiates card payments and bank transfers via" "HTTPS"
        bankPortal.webPortal -> bankPortal.cardService "manages debit and credit cards via" "HTTPS"
        bankPortal.webPortal -> bankPortal.statementsService "views monthly statements via" "HTTPS"
        bankPortal.webPortal -> bankPortal.directDebitService "manages standing orders and direct debits via" "HTTPS"

        bankPortal.mobileAppBackend -> bankPortal.accountService "manages accounts via" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.transactionService "submits deposits, withdrawals, and transfers via" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.paymentService "initiates card payments and bank transfers via" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.cardService "manages debit and credit cards via" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.statementsService "views monthly statements via" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.directDebitService "manages standing orders and direct debits via" "HTTPS"

        bankPortal.transactionService -> bankPortal.ledgerDb "updates the ledger with" "SQL"
        bankPortal.transactionService -> bankPortal.fraudDetectionService "scores transactions with" "HTTPS"
        bankPortal.transactionService -> bankPortal.eventQueue "publishes events to" "AMQP"

        bankPortal.notificationService -> bankPortal.eventQueue "consumes events from" "AMQP"

        bankPortal.statementsService -> bankPortal.ledgerDb "reads account movements from" "SQL"
        bankPortal.statementsService -> bankPortal.documentStore "writes statement PDFs to" "REST"

        bankPortal.batchScheduler -> bankPortal.ledgerDb "reads and writes for the nightly interest calculation and reconciliation" "SQL"
        bankPortal.batchScheduler -> bankPortal.customerDb "reads and writes for the nightly interest calculation and reconciliation" "SQL"

        bankPortal.paymentService -> bankPortal.cardService "is served by" "HTTPS"
        bankPortal.paymentService -> bankPortal.exchangeRatesService "is served by" "HTTPS"

        bankPortal.onboardingService -> bankPortal.customerDb "reads customer records from" "SQL"

        bankPortal.paymentService -> cardPaymentNetwork "routes card authorisations through" "HTTPS"
        bankPortal.onboardingService -> creditReferenceAgency "performs credit checks through" "HTTPS"
    }

    views {

        systemContext bankPortal "SystemContext" {
            include *
            autoLayout
            title "System Context for Bank Portal"
        }

        container bankPortal "Containers" {
            include *
            autoLayout
            title "Containers for Bank Portal"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Queue" {
                shape Pipe
            }
            element "Web" {
                shape WebBrowser
            }
            element "Cache" {
                shape Cylinder
            }
            element "DocumentStore" {
                shape Cylinder
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }
}

