        "structurizr.inspection.softwareSystem.documentation" "${val}"
    }
    model {
        s = softwareSystem "S" "a system with containers" {
            c1 = container "C1" "a container" "tech"
            c2 = container "C2" "another container" "tech"
            c1 -> c2 "calls" "tech"
        }
    }
    views {
        systemContext s "SC" { include * autoLayout }
        container s "CV" { include * autoLayout }
    }
    configuration { scope softwareSystem }
}`;
  const r = await tools.structurizr.inspect({ dsl }).then(v => JSON.stringify(v)).catch(e => "FAIL:" + (e&&e.message?e.message:String(e)));
  const hasDocError = r.includes("missing documentation");
  results[val] = hasDocError ? "still errors" : "SUPPRESSED -> " + r;
}
return results;

