const results = {};
for (const val of values) {
  const dsl = `workspace "T" "d" {
    properties {
        "structurizr.inspection.documentation" "${val}"
    }
    model {
        s = softwareSystem "S" "a system with containers" {
            c1 = container "C1" "a container" "tech"
            c2 = container "C2" "another container" "tech"
            c1 -> c2 "calls" "tech"
        }
        p = person "P" "a person"
        p -> s "uses" "HTTPS"
    }
    views {
        systemContext s "SC" {
            include *
            autoLayout
        }
        container s "CV" {
            include *
            autoLayout
        }
    }
    configuration {
        scope softwareSystem
    }
}`;
  const r = await tools.structurizr.inspect({ dsl }).then(v => JSON.stringify(v)).catch(e => "FAIL:" + (e&&e.message?e.message:String(e)));
  results[val] = r.includes("missing documentation") ? "errors" : "SUPPRESSED: " + r;
}
return results;"}

